		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Revenez vers le sud après Nesingwary : les Panthères et les Raptors de Strangleronce courent dans les clairières à l'ouest du camp vers la côte ; les anciens tigres tiennent les collines au sud-ouest.",
		["Bloodscalp trolls"] = "Trolls Bloodscalp",
		["Both roam the grass around the camp and along the road north."] = "Les deux parcourent l'herbe autour du camp et le long de la route vers le nord.",
		["Druid training"] = "Entraînement de druide",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Suivez la côte ouest vers le nord ; l'île hantée se trouve au large, à l'ouest du camp de Nesingwary. Il suffit de l'atteindre.",
		["For Archmage Ansirem in {zone:1416}"] = "Pour l'archimage Ansirem dans {zone:1416}",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluggle, un murloc rare sur la côte à l'ouest du camp, laisse tomber le {item:4614} : prenez-le si vous le croisez",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop."] = "Les Réducteurs de tête se tiennent plus loin dans la base ; les Commandos rôdent camouflés autour et dans la grotte. Ramassez les pages des Vertes collines quand elles tombent.",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Les registres de Herod se trouvent dans une hutte du côté ouest de la base ; son coffre est plus à l'est, près de l'entrée de la grotte.",
		["Panthers, raptors and elder tigers"] = "Panthères, raptors et anciens tigres",
		["River crocolisks"] = "Crocilisques des rivières",
		["Skullsplitter trolls"] = "Trolls Skullsplitter",
		["Snapjaw Crocolisks"] = "Crocilisques Gueule d'acier",
		["Stranglethorn Tigers"] = "Tigres de Strangleronce",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "Prenez la route vers le nord ; {npc:738} y patrouille, le camp se trouve dans les collines à l'ouest.",
		["The Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Les trolls Bloodscalp tiennent les ruines sur la côte à l'ouest du camp de Nesingwary.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Les trolls Skullsplitter tiennent les ruines à l'est de la route entre Nesingwary et {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Les tigres adultes rôdent dans les collines juste au sud et à l'ouest du camp.",
		["The haunted island"] = "L'île hantée",
		["The jungle ruins"] = "Les ruines de la jungle",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "Le minerai tombe des kobolds Sèche-moustache des {zone:1417}",
		["Young tigers and panthers"] = "Jeunes tigres et panthères",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, dans une caisse de {object:263}",
		["{npc:2495}, by the bank"] = "{npc:2495}, près de la banque",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, à l'étage de la taverne",
		["{npc:2832}, in the {object:56910}"] = "{npc:2832}, à la {object:56910}",
		["{npc:2859}, on the top floor by the docks"] = "{npc:2859}, au dernier étage près des quais",
		["{npc:469}, in the hut"] = "{npc:469}, dans la hutte",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, depuis {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} collectionne {item:2755} : les pages tombent de presque tous les humanoïdes de la jungle. Assemblez les pages en chapitres au fur et à mesure.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} et les raptors flagellants",
		["{npc:737}, in the tavern"] = "{npc:737}, dans la taverne",
		["{npc:773}, in the tavern"] = "{npc:773}, dans la taverne",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201} : faites simplement le tour du camp des chasseurs",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["Crushridge ogres"] = "Ogres Cassecrête",
		["Ebenezer Rustlocke"] = "Ebenezer Rustlocke",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves."] = "Escortez le professeur jusqu'à la plage au nord de la crique et protégez-le pendant qu'il travaille ; les nagas attaquent par vagues.",
		["Fly to {zone:1453}"] = "Prenez un vol pour {zone:1453}",
		["For {npc:1440} in {zone:1453}: keep it"] = "Pour {npc:1440} à {zone:1453} : gardez-la",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Seulement si Gluggle vous a donné le pendentif à Strangleronce",
		["Phizzlethorpe"] = "Phizzlethorpe",
		["Shaman training"] = "Entraînement de chaman",
		["South-east along the loch to the dig site."] = "Longez le loch vers le sud-est jusqu'au site de fouilles.",
		["Subdue the succubus"] = "Soumettez la succube",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Les deux épaves reposent dans la baie à l'ouest de la crique. Les cartes et les journaux sont à l'intérieur ; les gemmes gisent au fond de la mer autour. Des nagas Daguéchine nagent dans toute la baie.",
		["The western swamp"] = "Le marais occidental",
		["The wrecked caravan lies off the road near Biggs."] = "La caravane détruite se trouve en bord de route, près de Biggs.",
		["The wrecks"] = "Les épaves",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Retournez sur le pont : Ebenezer gît sous son extrémité côté Arathi.",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Longez la côte vers l'ouest jusqu'à la crique des gobelins ; Lolo monte la garde sur les rochers au-dessus.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Jeunes crocilisques, Tisseuses des pleurs et Jaguars du marécage parcourent tous le marais autour de la route.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} pour la cape de {npc:2438}, chez {npc:2381}, si vous n'en avez pas",
		["{item:3658}: Crushridge ogres"] = "{item:3658} : ogres Cassecrête",
		["{item:3659}: the {object:1760}"] = "{item:3659} : {object:1760}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Cathedral of Light",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, la Royal Library du donjon",
		["{npc:185335}, at the same circle"] = "{npc:185335}, sur le même cercle",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412} : trois bestioles à capturer en Arathi, en {zone:1443} et à Strangleronce",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589} : capturez-le, pour {quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} et {npc:2713}",
		["{npc:2713}'s errand"] = "La mission de {npc:2713}",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "{npc:2793}, un mage ogre, occupe la grotte à l'extrémité sud de la vallée des Witherbark.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} est enfermé dans une cage au nord du sanctuaire. Libérez-le et gardez-le en vie pendant la sortie ; son coffre vous attend ensuite au bord de la route.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vous lie l'incube",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} attend dans la cave de {object:2164}, dans {object:2101}. Utilisez le {item:6913} sur le cercle d'invocation et vainquez la succube invoquée. Si vous avez pris {quest:65602}, donnez-lui aussi la {item:190309}, placez-la sur le même cercle et vainquez l'incube.",
		["{quest:65602}, if you took it"] = "{quest:65602}, si vous l'avez prise",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Volez jusqu'à Theramore",
		["Greater Rock Elementals"] = "Elémentaires de roche supérieurs",
		["Lesser Rock Elementals"] = "Elémentaires de roche inférieurs",
		["Maraudine centaurs"] = "Centaures maraudine",
		["Ogres and buzzards"] = "Ogres et busards",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Revenez vers l'ouest jusqu'à la route et suivez-la vers le sud hors du {zone:1432}, par le col, jusqu'aux {zone:1418}. {npc:2910} et {npc:2860} campent côte à côte sur le site de fouilles.",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Partez au nord-est vers le site de fouilles abandonné ; la caisse de ravitaillement s'y trouve, parmi les ogres Crache-poussières.",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Partez au nord-est vers les ruines naines au nord des {zone:1418} ; le coffre se trouve parmi les nains Ombreforge. {npc:2745}, tout près, est élite : gardez vos distances.",
		["Rock Elementals"] = "Elémentaires de roche",
		["Shadowforge camp"] = "Camp Ombreforge",
		["Take the boat to Theramore from the far pier."] = "Prenez le bateau pour Theramore au quai le plus éloigné.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "Les ogres Crache-poussières campent juste au sud de la vallée ; chacun d'eux lâche des morceaux de métal. Des busards tournoient au-dessus de la plaine à l'est.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Les Elémentaires de roche ({npc:92}) errent au sud-est de {npc:2921} ; Busards géants ({npc:2831}) et Anciens coyotes des rochers ({npc:2729}) se partagent la plaine à leur ouest.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Les nains Ombreforge campent juste au nord du site de fouilles ; la carte froissée se trouve parmi leurs tentes. Les Tunneliers Ombreforge et les Tisseurs d'ombre Ombreforge portent la pioche de Ryedol. Des Coyotes des rochers parcourent les pentes alentour.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Le squelette de nain décrépi se trouve juste à l'est des ogres, en bordure du camp des troggs Cavepierre ; les Briseurs d'os Cavepierre et les Chamans Cavepierre alentour lâchent les flocons. Theldurin est assis près du camp en ruine plus au sud.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Les palourdes se trouvent sur la côte nord-ouest de Strangleronce, dans le guide suivant : gardez-la",
		["The excavation crate"] = "La caisse d'excavation",
		["The next guide starts in Theramore."] = "Le guide suivant commence à Theramore.",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "La tâche suivante du squelette, Murdaloc, attend le guide des {zone:1418} suivant, au niveau 43.",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "Le coffre du navire échoué se trouve sur le rivage, juste à l'ouest de la tour d'{npc:11863}.",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Theramore",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Des Ravageurs morts-vivants parcourent les champs d'ossements au sud du Village des Magram, à l'est du Convent de Mannoroc ; à l'extrême sud-est, utilisez la {item:15848} pour attirer les Spectres magrami.",
		["escort {npc:12277} back toward the graveyard"] = "escortez {npc:12277} jusqu'au cimetière",
		["for the Dustwallow loop in the next guide"] = "pour la boucle du marécage d'Âprefange, dans le guide suivant",
		["for {npc:2786} in {zone:1455}: keep it"] = "pour {npc:2786} à {zone:1455} : gardez-la",
		["for {npc:5637} in {zone:1455}: keep it"] = "pour {npc:5637} à {zone:1455} : gardez-la",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "seulement si vous avez des {item:2868} (fabriqués par un forgeron)",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277} est retenue dans le camp centaure à l'ouest du cimetière. Libérez-la et gardez-la en vie pendant la sortie ; elle s'arrête près du cimetière.",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, un chef centaure, campe sur la côte nord-ouest, au nord de la tour d'{npc:11863}.",
		["{npc:1470}, in the inn"] = "{npc:1470}, à l'auberge",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590} : attrapez-le, pour My Little Friends",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, à côté de {npc:2921}",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "Le test suivant de {npc:2921} demande de l'équipement fabriqué : passez-le.",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "La tâche suivante de {npc:5638}, {item:6245}, est un butin sur la côte lointaine : passez-la.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "Ignatz \"Puant\"",
		["Bloodsail camp"] = "Camp de la Voile sanglante",
		["Bloodsail pirates"] = "Pirates de la Voile sanglante",
		["Cold Eye Basilisks"] = "Basilics Oeil-de-glace",
		["Defeat the challengers and {npc:6238}"] = "Vainquez les adversaires et {npc:6238}",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Tout disciple de Zanzil peut laisser tomber le mélange ; {npc:2537} arpente le sud du camp.",
		["Gorilla hills"] = "Collines des gorilles",
