		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "La course suivante de {npc:2498} concernant Zanzil commence à {zone:1441} : passez-la.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} et {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nage au large de la côte nord-ouest, lors de la boucle nord",
		["{npc:384}: other colours, 20g"] = "{npc:384} : autres couleurs, 20 po",
		["{npc:4730}: other colours, 20g"] = "{npc:4730} : autres couleurs, 20 po",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields."] = "{npc:4966} tient la tour avec quelques déserteurs. Il se retourne contre vous : battez-le jusqu'à ce qu'il se rende.",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, dans la cathédrale de la Lumière",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} propose ensuite La Vigie des vents (1791) : la suite de l'arme Tourbillon, avec un élite à la fin, se trouve dans le guide de classe Guerrier Arme Tourbillon.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773} : pour {quest:2864} en {zone:1446}, gardez-la",
		["{npc:7955}: other colours, 20g"] = "{npc:7955} : autres couleurs, 20 po",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} est le grand bâtiment qui domine le port ; la plupart des donneurs de quête sont à ses étages ou sur les quais en dessous.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} se tient près de l'auberge ; {npc:4897}, une fournisseuse de métiers quelques pas au sud, vend les épices que veut Jarl.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} n'a pas de maître des chamans",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Perles bleues de Strangleronce",
		["On to Feathermoon"] = "En route pour le Bastion de Pennelune",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Partez au sud hors du {zone:1432}, par le col, jusqu'aux {zone:1418} ; {npc:2860} campe sur le site de fouilles.",
		["Take the boat to Theramore from the far pier."] = "Prenez le bateau pour Theramore au quai le plus éloigné.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "La tâche suivante de Talonaxe attend un guide des {zone:1425} ultérieur.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Les Dragonnets flamboyants nichent dans le ravin à l'est de {npc:2888} ; laissez tranquilles les Gardiens des terres brûlées (élites). Le {item:4612} tombe rarement : prenez-le s'il tombe pendant que vous tuez des monstres.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "Le squelette de nain décrépi se trouve en bordure du camp des troggs Cavepierre ; {quest:739}, le meurtrier d'Agmond, rôde parmi les Briseurs d'os Cavepierre.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Les deux premières cages se trouvent ensemble dans le village de Fanécorce au sud de {npc:5634} ; la troisième est dans le village suivant, à l'est. Chaque troll Witherbark peut lâcher un collier.",
		["Theramore"] = "Theramore",
		["Warlock: {quest:3631}"] = "Démoniste : {quest:3631}",
		["Witherbark villages"] = "Villages de Fanécorce",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} se tient sur les quais où accoste le bateau.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La quête suivante de {npc:2817} ne rapporte pas d'expérience : passez-la.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La tâche suivante de {npc:2888} est une chasse élite : passez-la.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "Le cocktail de {npc:5634} demande des ingrédients de Kalimdor : passez-le.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, à côté du maître de vol au sommet",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} paie toujours les colliers : rendez ceux en trop",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Giants and elementals"] = "Géants et élémentaires",
		["Gordunni ogres"] = "Les ogres Gordunni",
		["Grimtotem camp"] = "Le camp Totem sinistre",
		["Grimtotem tauren"] = "Taurens Totem sinistre",
		["Grind to 45"] = "Farmer jusqu'au niveau 45",
		["Hatecrest naga"] = "Nagas Hainecrête",
		["Hearth to Feathermoon."] = "Pierre de foyer vers le Bastion de Pennelune.",
		["Rage Scar yetis"] = "Yétis Griffe féroce",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Revenez vers l'ouest par la route, puis montez au nord dans les collines du Repaire des Griffes féroces. Tout yéti ici peut laisser tomber une peau ; l'un d'eux peut donner une {quest:7735}, que {npc:7852} McGrubben paie aussi.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Chevauchez vers l'est jusqu'au camp Gordunni dans les collines au sud-est de la vallée des yétis : des Démonistes Gordunni et des Chamans Gordunni tiennent le camp, des Brutes Gordunni errent sur les pentes alentour et plus au nord.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Chevauchez vers le nord dans la vallée des yétis. Tout Yéti Griffe farouche peut laisser tomber une peau épaisse ; {npc:5346} (niveau 48) rôde au milieu.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Chevauchez au nord-est jusqu'à l'avant-poste elfe de la nuit à la frontière de {zone:1441}.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Chevauchez vers l'ouest jusqu'au géant des montagnes amical au pied des collines. Les Marcheurs des terres et les Géants des falaises autour de lui sont élites : gardez vos distances.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Faites sonner la cloche chaque fois que {npc:7774} s'arrête pour vagabonder, et ramenez-la au sud jusqu'à {npc:7765}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Des Marcheurs des rivages, des Marcheurs des profondeurs et des Marcheurs des vagues (géants élites) arpentent la côte au nord du quai : frappez-en un avec l'{item:18904} et tuez le géant rétréci. Des Elémentaires marins et des Embruns dérivent dans les mêmes vagues.",
		["The courier's boat"] = "Le bateau du messager",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Marchez vers le sud sur l'île jusqu'aux ruines nagas ; le belvédère se trouve parmi elles.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "pour Tyrande Whisperwind à {zone:1457} : l'itinéraire vous y mène au niveau 47",
		["if you carry {quest:1100} from {zone:1441}"] = "si vous avez {quest:1100} de {zone:1441}",
		["{item:11463}, from the backpacks"] = "{item:11463}, dans les sacs à dos",
		["{npc:14637}'s refills are level 55: skip them."] = "Les recharges de {npc:14637} Fandazzle sont de niveau 55 : passez-les.",
		["{npc:3936}, beside him"] = "{npc:3936}, à côté de lui",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} Leafrunner erre dans les collines au nord de {npc:7765}, parmi les harpies Ruissenord ; sa cloche est dans le coffre à côté d'elle.",
		["{npc:7774}'s escort"] = "L'escorte de {npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, au sommet du bastion",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} attend la fin de la boucle sur le continent.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "Suivez la côte vers le sud jusqu'à la Crique des Gréements. Des Pirates des Mers du sud envahissent la plage et les bateaux : progressez par les bords et attirez-les un par un. {npc:7883} se tient de l'autre côté ; la cargaison volée de {npc:7881} se trouve dans le camp.",
		["Gives the {item:8585}"] = "Donne le {item:8585}",
		["He runs off to keep Rizzle busy"] = "Il s'éloigne pour occuper Rizzle Brassbolts",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Chevauchez vers l'est à travers les dunes jusqu'au Port Gentepression sur la côte nord-est.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "Chevauchez au nord-ouest jusqu'au Repaire nuisible, la ruche Centipaar dans les dunes. Tout Centipaar peut laisser tomber des Morceaux d'insecte Centipaar.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "Chevauchez vers le sud dans la {quest:3362}. Les Chardonniers collecteurs de rosée laissent tomber les glandes ; seules certaines sont pleines, gardez la Glande de rosée remplie. Les Chardonniers noueux et les Chardonniers taille-racine partagent la vallée. Les Chardonniers noueux sont de niveau 48-50, au-dessus de vous : attirez-les un par un.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Chevauchez au sud-ouest jusqu'à la Base des Cognedunes. Des Brutes Cognedune et des Massacreurs Cognedune (46-48) la remplissent ; {npc:12046} (49) se tient au centre entouré de gardes : éliminez-les d'abord.",
		["Rizzle's plans"] = "Les Plans de Rizzle",
		["The Wanted poster beside him"] = "L'affiche Avis de recherche à côté de lui",
		["Wastewander bandits"] = "Les bandits Bat-le-désert",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "Pendant que {npc:4709} retient Rizzle Brassbolts, ses plans sont laissés sans surveillance dans le camp gnome de l'autre côté de la piste.",
		["for {zone:1457}: the route takes you there at 47"] = "pour {zone:1457} : l'itinéraire vous y mène au niveau 47",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, à l'est de la ville",
		["{npc:5955}'s escort"] = "L'escorte de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, près du château d'eau",
		["{npc:7408}, next to him"] = "{npc:7408}, à côté de lui",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "L'ingrédient suivant de {npc:7583} pousse dans les {zone:1425}, et l'itinéraire n'y revient jamais : passez-le.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, dans la taverne du port",
		["{quest:2864}, north side of town"] = "{quest:2864}, au nord de la ville",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "Les Sangliers cendrés et les Basilics Rougepierre partagent les pentes au sud-ouest du donjon. Evitez les Sangliers infernaux plus au sud : ils sont de niveau 52.",
		["Boars and basilisks"] = "Sangliers et basilics",
		["Hearthstone on cooldown? Ride back north-west."] = "Pierre de foyer en recharge ? Revenez au nord-ouest.",
		["Ride back north to Ironband's camp."] = "Revenez vers le nord jusqu'aux Excavations de Baguefer.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Chevauchez vers l'est le long de la rive sud du Loch jusqu'aux Excavations de Baguefer.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "Chevauchez vers l'est à travers le {zone:1430} jusqu'au {zone:1435}, puis vers le sud par la route jusqu'aux {zone:1419}. Le camp des mages de sang est le premier arrêt au bord de la route.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "Chevauchez vers l'ouest : les Raillecrocs affamées errent dans les collines arides juste au sud du camp des mages de sang ; les Aiguillonneurs scorpoks (niveau 50) parcourent le centre du nord. Les vautours {npc:5982} tournoient au-dessus de tout cela. Attirez-les un par un.",
		["Scorpoks and snickerfangs"] = "Scorpoks et Raillecrocs",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Franchissez le portail vers {zone:1457}. Le Temple de la Lune se trouve au sud de la cité.",
		["Temple of the Moon"] = "Temple de la Lune",
		["The bloodmages"] = "Les mages de sang",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "Le second palier des mages de sang paie les mêmes morceaux avec un objet d'amélioration et sans expérience : passez-le.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "Les maîtres druides se trouvent dans l'Enclave cénarienne ; {zone:1455} n'en a aucun",
		["the book on her table"] = "le livre sur sa table",
		["the soil comes from {zone:1449}, later"] = "la terre vient du {zone:1449}, plus tard",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, au sommet de l'arbre",
		["{npc:7740}, beside her"] = "{npc:7740}, à côté d'elle",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744} : le guide précédent vous lie ici, cette étape se coche donc généralement aussitôt",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "La course suivante de {npc:7907} Lightwind mène en {zone:1446} : passez-la.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916} : gardez-la, les plumes viennent à la fin du guide des {zone:1428}",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, au sommet du donjon",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "Pour {npc:8256} à {zone:1455}, plus tard",
		["Golems and elementals"] = "Golems et élémentaires",
		["Greater Lava Spiders"] = "Araignées de lave incendiaires",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Les Golems de guerre lourds patrouillent au fond du Chaudron sous Velarok Lamevent ; les Elémentaires de magma dérivent parmi eux. Golems et élémentaires laissent tomber l'huile, les élémentaires les cœurs.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "Les Sous-chefs Sombrefer et les Esclavagistes Sombrefer mènent les esclaves dans tout le Chaudron, et chacun d'eux peut porter une {item:10551}. Les Forge-vapeur Sombrefer travaillent aux fourneaux du centre (la {item:18959}), les Guetteurs Sombrefer se tiennent sur les crêtes sud (la Longue-vue de guetteur). Tout {object:147516} peut laisser tomber la {item:11818} : gardez-la.",
		["The Grimesilt outhouse"] = "Les toilettes de Crasseboue",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La tâche suivante du prisonnier, Grand livre de {zone:1446}, vous envoie au {zone:1435} et au {zone:1445} : passez-la.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Les araignées errent sur les plateaux et autour des bassins de lave au sud-ouest de la gorge.",
		["The {object:179827} board"] = "Le panneau {object:179827}",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734} : le guide précédent vous ramène ici par la pierre de foyer, cette étape se coche donc généralement aussitôt",
		["{object:147516} dwarves"] = "Nains {object:147516}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus se tient à côté du roi Magni dans {object:171709}.",
		["Bind and train"] = "Lier la pierre de foyer et s'entraîner",
		["Bones and equipment"] = "Os et équipement",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Traversez le sud du cratère jusqu'à {npc:9619}, près de la rampe.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Les Os de dinosaure jonchent le sol au sud-ouest, parmi les stégodons : ceux-ci sont élites, ramassez les os autour d'eux et prenez le reste sur les Dimeurtrodons. L'{item:11112} de l'expédition se trouve dans la jungle sud-ouest.",
		["Eastern Pylon"] = "Le Pylône est",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Se termine auprès de {npc:9298} au {zone:1452} : gardez-la",
		["Escort {npc:9999}"] = "Escorter {npc:9999}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Pour {npc:7775} en {zone:1444} : gardez-la",
		["Four rune rubbings in {zone:1447}: keep it"] = "Quatre estampes de runes en {zone:1447} : gardez-la",
		["Grind to 50"] = "Monter au niveau 50",
		["Grind to 51"] = "Monter au niveau 51",
		["Lar'korwi Mates and the raft"] = "Compagnes de Lar'korwi ({npc:9683}) et le radeau",
		["Northern Pylon"] = "Le Pylône nord",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Descendez la rampe dans le cratère : {npc:9619} campe à son pied.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Chevauchez vers le nord par le côté est jusqu'au plateau des gorilles. {npc:9622}, un gorille de niveau 55, se tient dans sa grotte la plus profonde : éliminez d'abord les gorilles de l'entrée.",
		["Ride north along the western jungle back to the refuge."] = "Remontez vers le nord par la jungle ouest jusqu'au refuge.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "Chevauchez vers le sud le long des falaises est jusqu'à {npc:9619}, au pied de la rampe.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Descendez vers le sud par le côté est. Les Jeunes dimeurtrodons paissent dans la jungle est et les {npc:9165} volent près des falaises est ; les deux laissent tomber les écailles de {npc:9998}.",
		["Ride west back to the refuge."] = "Revenez vers l'ouest jusqu'au refuge.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "Chevauchez vers l'ouest depuis {npc:9619} : la ruche silithide occupe le sud du cratère. Utilisez la Fiole rayée sur un couvoir, une salle où pendent des larves. Les guêpes et ouvriers Gorishi laissent tomber {quest:3764} ; les {npc:9166} nichent sur les falaises sud s'il vous faut encore des victimes.",
		["The Gorishi hive"] = "La ruche Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Les Compagnes de Lar'korwi ({npc:9683}) rôdent dans la jungle à l'ouest de {npc:9619}. Le radeau échoué gît sur la rive du lac là-bas ; le petit paquetage est dans l'eau à côté. Gardez la boussole, la carte et la clé pour {npc:8737}. N'importe quelle bête du cratère peut lâcher {item:11116} : faites un clic droit dessus.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "Le battrodon mort se trouve au bord de l'eau au nord de {npc:9619}.",
		["The east side"] = "Le côté est",
		["The pelts come after loop 2, on the gorilla plateau"] = "Les peaux viennent après la boucle 2, sur le plateau des gorilles",
		["The pylon stands on the eastern cliffs."] = "Le pylône se dresse sur les falaises est.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "Le pylône se dresse sur la pente à l'est du refuge. Les {npc:9166} tournoient sur les pentes autour : ils comptent pour {npc:9997} et laissent tomber les écailles de {npc:9998}.",
