t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Retournez au camp, au nord.",
		["Back to {object:3202}"] = "Retour à {object:3202}",
		["Back to {object:3202}."] = "Retour à {object:3202}.",
		["Basilisks and the Bloodscalp village"] = "Basilics et village Bloodscalp",
		["Bloodscalp headhunters"] = "Chasseurs de tête Bloodscalp",
		["Bloodscalp ruins"] = "Ruines Bloodscalp",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "À l'est des ogres, les Panthères Ombregueule (37-38) rôdent invisibles jusqu'à leur attaque ; les Tigresses de Strangleronce parcourent le même terrain et lâchent parfois un Croc de tigresse en parfait état. Les Crocilisques Gueule d'acier bordent la rivière juste à l'ouest de la jungle ; gardez leurs peaux pour {npc:2495}.",
		["Elder tigers and Lashtail raptors"] = "Anciens tigres et raptors flagellants",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "Suivez la route vers le nord depuis {object:3202} ; le camp de chasse de Nesingwary se trouve sur la colline au nord-est de la rivière. Dès maintenant, gardez chaque page de {quest:338} ramassée : {npc:716} les demandera plus tard.",
		["Follow the road south to {object:3202}."] = "Suivez la route vers le sud jusqu'à {object:3202}.",
		["Green Hills pages"] = "Pages des Vertes collines",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "Allez vers l'ouest après le camp. Les Raptors de Strangleronce (33-34) chassent dans les clairières, et les trolls Bloodscalp tiennent les ruines de la côte : chaque Bloodscalp peut lâcher une défense. Ils lâchent très rarement un {item:4614} : si vous en obtenez un, lisez-le.",
		["Hearth to {object:3202}"] = "Pierre de foyer vers {object:3202}",
		["Jungle Stalkers"] = "Traqueurs de la jungle",
		["Lashtail raptors"] = "Raptors flagellants",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "Quittez {zone:1458} par l'ascenseur et montez à travers les ruines jusqu'aux tours des zeppelins ; le zeppelin pour {object:3202} est celui de la tour sud-ouest.",
		["Mistvale gorillas"] = "Gorilles de Valbrume",
		["Mosh'Ogg camp"] = "Camp Mosh'Ogg",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "Les pages de {item:2755} tombent à environ 1 % chacune sur les trolls Bloodscalp et Skullsplitter ; gardez chaque page ramassée et cherchez le reste à l'hôtel des ventes. {npc:716} prend les chapitres plus loin dans ce guide.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "Les pages de {item:2755} tombent à environ 1 % chacune sur les trolls Bloodscalp et Skullsplitter ; prenez ce qui tombe et cherchez le reste à l'hôtel des ventes.",
		["Raptors and the Bloodscalp trolls"] = "Raptors et trolls Bloodscalp",
		["Ride back south to {object:3202}."] = "Retournez au sud jusqu'à {object:3202}.",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "Allez vers le nord après le camp de Nesingwary jusqu'au lac. Les Géologues de la KapitalRisk (34-36) travaillent dans les camps de sa rive ouest ; ils portent les Cristaux réduits.",
		["Shadowmaw jungle and the Snapjaw river"] = "Jungle des Ombregueule et rivière des Gueule d'acier",
		["Shadowmaw panthers"] = "Panthères Ombregueule",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "Les Tigres de Strangleronce et les Panthères (32-33) parcourent les collines à l'est du camp, le long du lac.",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "Prenez le zeppelin pour {zone:1454} à la tour à l'ouest de {object:3202} et entraînez-vous en ville avant de repartir.",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "Les Chasseurs de tête Bloodscalp (36-37) du village de la côte portent les têtes réduites.",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "Les trolls Bloodscalp tiennent les ruines de la côte au nord du récif et le village plus loin ; chacun peut lâcher un {item:3915}. Continuez à ramasser les pages de {quest:338}.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "Les Anciens tigres de Strangleronce (34-35) parcourent les collines au sud-ouest du camp ; les Raptors flagellants (35-36) chassent plus au sud, vers {object:3202}.",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Les Traqueurs de la jungle (40-41) chassent sur la côte au sud de {object:3202}. Ils sont bien au-dessus de votre niveau : attirez-les un par un et reposez-vous entre les combats.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "Les Raptors flagellants (35-36) chassent dans la jungle juste au nord-est de {object:3202}.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "Les ogres Mosh'Ogg campent dans les collines juste à l'est de {object:3202}. Tuez une Brute Mosh'Ogg et un Sorcier-docteur Mosh'Ogg (36-37) ; attirez-les un par un.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "Les Panthères Ombregueule (37-38) rôdent dans la jungle à l'est des collines Mosh'Ogg et au nord-est vers le lac ; elles attaquent en camouflage. Ramassez chaque page des Vertes collines trouvée en chemin.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Les Panthères Ombregueule viendront bien plus tard, près de {object:3202}",
		["The camp by the river"] = "Le camp près de la rivière",
		["The zeppelin lands at the tower on the west side of the camp."] = "Le zeppelin arrive à la tour à l'ouest du campement.",
		["Tigers and panthers"] = "Tigres et panthères",
		["Venture Co. camp"] = "Camp de la KapitalRisk",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "À l'ouest après le camp, des Basilics de cristal (34-35) se tiennent sur les rochers ; chaque Bloodscalp du village plus loin peut lâcher une oreille.",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "Les Jeunes tigres de Strangleronce rôdent à l'ouest du camp, les Jeunes panthères au sud et à l'est.",
		["Young tigers and panthers"] = "Jeunes tigres et panthères",
		["Zeppelin to {object:3202}"] = "Zeppelin pour {object:3202}",
		["Zeppelin towers"] = "Tours des zeppelins",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495} : les peaux de Gueule d'acier récupérées plus tôt",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497} : pour les Hautes-terres Arathies, plus loin sur l'itinéraire",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901} : {npc:3527} et votre {item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "{npc:729}, un tigre de niveau 37, rôde au sommet de la colline au sud-ouest du camp.",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "Le camp des chasseurs disparus de {npc:773} est celui de Nesingwary : marchez parmi ses tentes et l'enquête est terminée. Des Crocilisques des rivières se trouvent le long de la rivière sous le camp.",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Boulderfist camp"] = "Camp Rochepoing",
		["Coyotes and buzzards"] = "Coyotes et busards",
		["Daggerspine shore"] = "Rivage des Daguéchine",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "Escortez le professeur jusqu'au rivage. Deux nagas Daguéchine lui tendent une embuscade en chemin : restez près de lui.",
		["Fleshstalker raptors"] = "Raptors charognards",
		["Fly to {object:3202}"] = "Volez jusqu'à {object:3202}",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "Suivez la route vers le nord ; le camp de {npc:4618} est sur le chemin.",
		["Greater Rock Elementals"] = "Elémentaires de roche supérieurs ({npc:2736})",
		["Highland raptors"] = "Raptors des hautes-terres",
		["Into the {zone:1418}"] = "Vers {zone:1418}",
		["Lesser Rock Elementals"] = "Elémentaires de roche inférieurs ({npc:2735})",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "Au nord-est de Trépas-d'Orgrim, les kobolds Sèche-moustache exploitent la gorge ; les Kobolds à l'entrée, et les Terrassiers et Géomètres plus loin, lâchent tous les Poussières de Myzrael.",
		["Ride north; the outer circle stands in the middle of the highlands."] = "Chevauchez vers le nord ; le cercle extérieur se dresse au milieu des hautes-terres.",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Chevauchez vers le sud-ouest jusqu'à la crique des gobelins sur la côte sud. {npc:2766} fait le guet sur la falaise au-dessus.",
		["Rock Elementals"] = "Elémentaires de roche ({npc:92})",
		["Stonevault troggs"] = "Troggs Cavepierre",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "Prenez le zeppelin d'{zone:1454} à la tour à l'ouest de {object:3202}.",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "Les Elémentaires de roche supérieurs ({npc:2736}) (42-44, bien au-dessus de vous) errent dans les ravins du sud-ouest ; les brassards tombent environ une fois sur cinq. Attirez-les un par un et reposez-vous entre les combats, ou laissez-les. Continuez à tuer en chemin les coyotes et busards qu'il vous manque.",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "Le Syndicat tient le manoir fortifié et sa ferme au nord-ouest ; leurs Malandrins, Mercenaires et Eclaireurs portent les Amulettes de pierre de sang ({item:4495}).",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "Les trolls Witherbark tiennent le village dans les collines du sud-est. Les Lanceurs de haches gardent les huttes extérieures ; les Sorciers-docteurs et Chasseurs de têtes tiennent le cœur du village.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Le cercle intérieur se trouve au sud du cercle ouest, à l'est de Stromgarde.",
		["The next guide heads into {zone:1445}."] = "Le prochain guide part vers le {zone:1445}.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "La forteresse orque au bout est de la route. {npc:2851}, la maîtresse des coursiers du vent, se tient près de la porte.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "Les petits élémentaires dérivent dans la plaine juste à l'ouest du camp de {npc:2921}. Tout élémentaire de roche de la zone peut lâcher les Fragments d'élémentaire de roche ({item:7848}) de {npc:6868} : gardez-les.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "La tâche suivante de la pierre demande Fozruk, un élite de niveau 42 : laissez-la.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} se trouvent tout au fond de la gorge.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entraînez-vous pendant que vous êtes à {zone:1458} : les maîtres se trouvent dans {object:36070}, {object:36073} et {object:36082} (paladins : {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "À l'ouest de la crique, les Ecumeurs ({npc:2595}) et Sorcières Daguéchine (38-40) tiennent le rivage : attirez-les un par un. Les deux épaves gisent dans les hauts-fonds au large, les cartes et journaux à l'intérieur ; les gemmes reposent au fond de la mer autour des épaves.",
		["Zeppelin to the {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["Zeppelin tower"] = "Tour du zeppelin",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "pour {npc:5395} en {zone:1443}, dans le prochain guide",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}, pour Jarl « Oeil-des-marais » au {zone:1445}",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "La suite {quest:678} de {npc:2771} vise des élites Rochepoing : laissez-la.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920} : seulement si vous avez {item:2868} ({skill:164} ou l'hôtel des ventes)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661} n'a pas de maître des chasseurs ni des chamans : prenez plutôt le zeppelin d'{zone:1454} à la même tour et entraînez-vous en ville, puis prenez le zeppelin de {zone:1458} à la tour devant la porte principale d'{zone:1454}.",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "Araignées Sombrecroc",
		["For {npc:2519} at {object:3202}, in the next guide"] = "Pour {npc:2519} à {object:3202}, dans le guide suivant",
		["Hearth to Shadowprey"] = "Pierre de foyer vers Proie-de-l'Ombre",
		["Kodo bones and ghosts"] = "Os de kodo et fantômes",
		["Maraudine totems"] = "Totems maraudine",
		["Mirefin murlocs"] = "Murlocs Aileron boueux",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "Ramassez les os de kodo éparpillés dans le cimetière et utilisez {item:15848} parmi les os : les fantômes qu'elle attire laissent tomber l'ectoplasme.",
		["Ride back west to Brackenwall with the head."] = "Retournez à l'ouest à Mur-de-Fougères avec la tête.",
		["Ride north up the road to the hut by the road north of the graveyard."] = "Remontez la route vers le nord jusqu'à la hutte au bord de la route, au nord du cimetière.",
		["Ride on south-west to Shadowprey."] = "Continuez au sud-ouest jusqu'à Proie-de-l'Ombre.",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Retraversez le marais vers l'ouest. Les Crache-venin Sombrecroc des crêtes au nord de Mur-de-Fougères laissent tomber les poches de venin. Des Infiltrateurs de Theramore (35-36) rôdent dans les mêmes bois : ils sont camouflés, regardez bien.",
		["Slitherblade coast"] = "Côte des Ondulame",
		["Stinky Ignatz"] = "Ignatz \"Puant\"",
		["Swamp Eye Jarl"] = "Jarl \"Oeil-des-marais\"",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "À l'embranchement, prenez la route du nord jusqu'au village ogre de Mur-de-Fougères.",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "Les araignées de Sombrebrume grouillent à l'entrée de la caverne au nord-ouest de Mur-de-Fougères ; toutes laissent tomber des yeux.",
		["The next guide takes you back to {zone:1434}."] = "Le guide suivant vous ramène à {zone:1434}.",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "seulement si vous avez une {item:3853} ({skill:164} ou Hôtel des ventes)",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, à l'entrée sud du village, là où arrive la route",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395} et {npc:5412} se tiennent dans le poste juste à l'ouest du camp de {npc:11596}.",
		["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791} : le guide précédent vous lie ici, cette étape se coche donc généralement aussitôt",
		["{object:20985}, beside the manor"] = "{object:20985}, à côté du manoir",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, maintenant que {npc:4791} a lu le rapport",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "Cristaux de draenéthyste",
		["Fly to {object:3202}"] = "Vol pour {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Suivez la côte vers le sud. Les explorateurs nagas pataugent le long du rivage et portent les bottes de roseaux ; {object:759} bouillonne dans les collines juste à l'est.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "Plus au nord, les gobelins de la KapitalRisk creusent la mine à l'est de la route ; mineurs, contremaîtres, géomètres et bricoleurs laissent tous tomber les cristaux.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Donnez les crocs à Unbagwa et restez près de lui : il appelle trois vagues de gorilles, puis {npc:1514}. Combattez-les un par un.",
		["Hearth to {object:3202}"] = "Pierre de foyer vers {object:3202}",
		["Into the {zone:1435}"] = "Vers {zone:1435}",
		["Jungle stalkers"] = "Traqueurs de la jungle",
		["Mistvale gorillas"] = "Gorilles de Valbrume",
		["Naga shore and the {object:759}"] = "Rivage des nagas et {object:759}",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "Au nord-est de Valbrume, les disciples de Zanzil campent dans la jungle ; chacun d'eux peut porter le mélange.",
		["Pirate ghosts"] = "Pirates fantômes",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Chevauchez vers le nord jusqu'aux ruines Skullsplitter à l'est de la mine de la KapitalRisk ; attirez les chasseurs de têtes et les berserkers un par un. {npc:1059} garde les ruines du sud-ouest, et un tas de crânes trophées se trouve au nord des ruines. Tout Skullsplitter peut laisser tomber une défense ou un collier : les colliers sont la partie lente, alors continuez à tuer dans le camp des guerriers au nord des ruines jusqu'à les avoir tous.",
		["Ride north up the road to the hunters' camp."] = "Remontez la route vers le nord jusqu'au camp des chasseurs.",
		["Ride north up the road; the hunters camp on the hill above the river."] = "Remontez la route vers le nord ; les chasseurs campent sur la colline au-dessus de la rivière.",
		["Ride north-west to {object:3202}."] = "Chevauchez vers le nord-ouest jusqu'à {object:3202}.",
		["Ride west to {object:3202}."] = "Chevauchez vers l'ouest jusqu'à {object:3202}.",
		["Sawtooth crocolisks"] = "Crocilisques Dents-de-scie",
		["Sawtooth snappers"] = "Mordeurs Dents-de-scie",
		["Skullsplitter warriors"] = "Guerriers Skullsplitter",
		["The Bloodsail ships"] = "Les navires de la Voile sanglante",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Les gorilles parcourent la vallée autour d'Unbagwa. Les anciens laissent tomber les abats ; tous peuvent laisser tomber un croc.",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "Les derniers crânes sont dans les ruines un peu à l'ouest, sur le chemin du retour vers {object:3202}.",
		["The next guide starts here and takes you to {zone:1446}."] = "Le guide suivant commence ici et vous emmène en {zone:1446}.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "Les crânes trophées suivants se trouvent dans les petites ruines juste au nord du camp des guerriers.",
		["The snappers line the strand south of the post."] = "Les mordeurs bordent la grève au sud du poste.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Les raptors traqueurs chassent dans la jungle au sud de {object:3202}, vers la côte ouest.",
		["Venture Co. mine"] = "Mine de la KapitalRisk",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "À l'ouest de l'expédition, les chefs Bloodscalp {npc:1061} et {npc:1062} se tiennent ensemble dans les Ruines de Zul'Kunda. Éliminez d'abord leurs gardes, puis attirez-les.",
		["Zanzil's camps"] = "Les camps de Zanzil",
		["Zul'Kunda"] = "Ruines de Zul'Kunda",
		["Zul'Mamwe"] = "Ruines de Zul'Mamwe",
		["for Stoley in {zone:1446}"] = "pour Stoley en {zone:1446}",
		["for a later stop in the {zone:1435}"] = "pour une étape ultérieure dans {zone:1435}",
		["for later: the {zone:1425}, around level 48"] = "pour plus tard : {zone:1425}, vers le niveau 48",
		["the {object:2076}"] = "le {object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "le {object:2076}, à côté de {npc:2497}",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "Camps Bat-le-désert de l'est",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Grimtotem camp"] = "Camp du Totem sinistre",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Continuez à l'ouest jusqu'à la côte. Les Enfouisseurs côtiers et les Claque-pinces côtiers des plages laissent tomber la Balise de détresse OOX-22/FE environ une fois sur quarante : si vous l'obtenez, utilisez-la pour commencer la quête.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Au nord des gnolls, les ogres tiennent un avant-poste sur une colline ; attirez les Ogres-mages Gordunni vers vous. Le Cobalt Gordunni est dans les tas de terre autour de l'avant-poste, et le Parchemin Gordunni est par terre à l'intérieur.",
		["Ride north-east to the goblin harbour on the coast."] = "Allez au nord-est jusqu'au port gobelin sur la côte.",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "Allez à l'ouest jusqu'au centre de {zone:1444}. Tuez un {npc:5308}, utilisez {item:10699} sur son cadavre et tuez l'esprit qui s'en élève.",
		["Riding at 40"] = "Monte au niveau 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "La monte demande le niveau 40 et coûte 100 pièces d'or ; l'apprendre vous donne une monture. {npc:4752} l'enseigne aux orcs dans {object:172958}, près du chenil de {npc:3362} ; aucun maître de monte skyborne n'est connu, les Éolides essaient donc aussi {npc:4752}. Les autres montures de votre race coûtent 20 pièces d'or chacune : Objets de collection, Montures · Niveau 40 a un guide pour chacune.",
		["Rogue Vale screechers"] = "Hurleurs des vallées insoumis",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "Plus au sud sur la côte, les pirates des Mers du sud tiennent la crique. {npc:7883} et la cargaison volée sont sur les quais, tout au fond. Tout pirate peut laisser tomber un Chapeau de pirate des Mers du sud, les Kidnappeurs des mers du Sud le plus souvent.",
		["Southern Gordunni ruins"] = "Ruines Gordunni du sud",
		["Southern Wastewander camps"] = "Camps Bat-le-désert du sud",
		["Sprite darters and Woodpaw alphas"] = "Fées fléchetteuses et Alphas Griffebois",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Les taurens du Totem sinistre campent à côté du bosquet des Fées fléchetteuses ; Ecumeurs, Naturalistes et Chamans portent tous des Cornes de Totem sinistre.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "Les gnolls Griffebois campent dans les collines juste au nord-ouest de Mojache ; chacun peut laisser tomber une Crinière de gnoll Griffebois.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "La ruche des Zukk'ash s'enfonce dans les collines au sud-est du camp ; {quest:7731} attend dans sa chambre la plus profonde.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Le Plan de bataille des Griffebois se trouve dans le camp Griffebois au sud de Mojache.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "Les Fées fléchetteuses voltigent au-dessus du bosquet juste à l'ouest de Mojache ; presque toutes laissent tomber une aile. Les Alphas Griffebois dirigent les camps au sud-ouest : tuez-les dans l'heure.",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "Le zeppelin pour {object:3202} part de la tour juste au nord-est de la grande porte de {zone:1454}.",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "Le zeppelin pour {zone:1454} part de la tour à côté de {object:3202} ; il arrive juste devant la grande porte de {zone:1454}.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Loups : {npc:3362}, à côté de {npc:4752}.",
		["Woodpaw battle map"] = "Plan de bataille des Griffebois",
		["Woodpaw north camp"] = "Camp Griffebois du nord",
		["Zeppelin to {object:3202}"] = "Zeppelin pour {object:3202}",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["Zeppelin tower"] = "Tour des zeppelins",
		["for the {zone:1425}, around level 48"] = "pour {zone:1425}, vers le niveau 48",
		["for {zone:1454}, around level 45"] = "pour {zone:1454}, vers le niveau 45",
		["the {object:150075} in the square"] = "l'{object:150075} sur la place",
		["water pouches in your bags"] = "Outres de Bat-le-désert dans vos sacs",
		["{npc:3690}, riding trainer"] = "{npc:3690}, maître de monte",
		["{npc:4752}, riding trainer"] = "{npc:4752}, maître de monte",
		["{npc:4773}, riding trainer"] = "{npc:4773}, maîtresse de monte",
		["{npc:7953}, riding trainer"] = "{npc:7953}, maître de monte",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115} : pour {zone:1454}, vers le niveau 45",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579} : les hurleurs vivent à {zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863} : dans une heure",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "Grottes des dragons",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Forest walkers"] = "Marcheurs des bois",
		["Frayfeather hippogryphs"] = "Hippogryphes Aigreplume",
		["Monstrous Crawlers"] = "Clampants monstrueux",
		["Murlocs of the Misty Reed"] = "Murlocs de Brumejonc",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "Au nord-ouest le long de la route, les Yétis Griffe féroce vivent autour des grottes dans les collines. Chacun peut aussi laisser tomber l'objet qui lance la quête {quest:7738}.",
		["Northspring harpies"] = "Harpies Ruissenord",
		["Onyxia's eggs"] = "Oeufs d'Onyxia",
		["Rage Scar yetis"] = "Yétis Griffe féroce",
		["Ride back north to Brackenwall."] = "Retournez au nord jusqu'à Mur-de-Fougères.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Suivez la route vers l'ouest ; le parchemin se trouve au bord de l'eau, à l'extrême ouest du marais.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Des Elémentaires marins et des Embruns longent le rivage autour du quai. Zappez d'abord les géants avec {item:18904} : rétrécis, ils perdent leur force d'élite. Les Marcheurs des rivages pataugent dans l'eau ; les Marcheurs des terres et les Géants des falaises parcourent les collines plus au nord.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Au sud du val, les Hippogryphes Aigreplume nichent sur les pentes ; presque tous laissent tomber des Tendons résistants et des Fragments métalliques.",
		["Sprite darters and forest walkers"] = "Fées fléchetteuses et Marcheurs des bois",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Les Murlocs des marais vivent sur la grève au sud du poste ; les Cracheurs des marais longent le rivage à l'est et les Dévoreurs des marais sont plus à l'ouest, autour des huttes de la rive ouest.",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "Les Clampants monstrueux arpentent les plages de la côte est, rares et dispersés : tuez tous ceux que vous voyez en descendant vers le sud.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Les Harpies Ruissenord nichent sur les crêtes à l'extrême nord-ouest. Elles sont de niveau 48-50, quelques niveaux au-dessus de vous : les Imploratrices célestes Ruissenord soignent, tuez-les donc en premier et attirez-les une par une.",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "Les mêmes murlocs, plus les Oracles des marais, qui restent près des huttes de la rive ouest.",
		["The small Horde post on the southern shore."] = "Le petit poste de la Horde sur la rive sud.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Les Fées fléchetteuses voltigent au-dessus du bosquet juste à l'ouest du camp et portent les {item:9589} ; les Marcheurs des bois errants, un peu plus à l'ouest, portent les Bûches fendues.",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "Le zeppelin pour {zone:1454} part de la tour à côté de {object:3202} ; il arrive juste au nord-est de la grande porte de {zone:1454}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["Zeppelin tower"] = "Tour des zeppelins",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "pour l'{npc:5598} dans {zone:1425}, vers le niveau 48",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "pour le {object:2555} à {zone:1445}, plus loin dans ce guide",
		["for the {zone:1425} owlbeasts, around level 48"] = "pour les chouettards de {zone:1425}, vers le niveau 48",
		["the {object:2555}"] = "le {object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500} est un élite : un groupe est conseillé. Frappez-le jusqu'à ce qu'il abandonne, puis faites votre rapport à {npc:4501}.",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875} : pour {npc:7010} à {zone:1454}, vers le niveau 50",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}, puis {object:172960} et {object:172961}.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, butin rare",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Dark Iron Lookouts"] = "Guetteurs Sombrefer ({npc:8566})",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "Plus au sud, l'Équipement d'analyse de Scrimshank se trouve à l'entrée d'une ruche Centipaar.",
		["Greater Lava Spiders"] = "Grandes araignées de lave",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "Les Golems de guerre lourds ({npc:5854}) patrouillent dans le Chaudron sous Velarok et lâchent l'huile ; les Elémentaires de magma et flamboyants ({npc:5850}) qui dérivent parmi eux lâchent les cœurs. Les Sous-chefs Sombrefer ({npc:5846}) et les Esclavagistes mènent les esclaves sur les chemins ; un Esclavagiste peut lâcher {item:11818} : gardez-la.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Sa demande suivante exige le {item:10552} sur des cultistes élites : laissez-la.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Seulement avec la {item:11818} : retournez à l'est jusqu'aux {object:173265} du site de fouilles.",
		["Scrimshank's gear"] = "Équipement d'analyse de Scrimshank",
		["South down the road again."] = "Redescendez la route vers le sud.",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "Au sud-est de Gadgetzan, les bandits Bat-le-désert campent dans les dunes ; {npc:7847} se tient dans le camp est.",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Les Guetteurs Sombrefer ({npc:8566}) se tiennent sur les crêtes autour des tours de guet au sud du Chaudron ; environ un sur dix porte {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Les Forge-vapeur Sombrefer ({npc:5840}) travaillent aux fourneaux au milieu du Chaudron ; la moitié porte une {item:10551}, un sur dix {item:18959}. Esclaves, Esclavagistes et Sous-chefs portent aussi des dagues.",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Les Grandes araignées de lave rôdent sur les plateaux et autour des bassins de lave au sud-ouest de la gorge.",
		["The Steamsmiths' furnaces"] = "Les fourneaux des Forge-vapeur",
		["The {object:179827} board"] = "Le panneau {object:179827}",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "À l'ouest de Gadgetzan, utilisez le {item:8584} près du point d'eau du camp troll.",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "À l'ouest du camp, les créatures cactus remplissent la vallée ; seuls les Chardonniers collecteurs de rosée portent une glande de rosée. La plupart des monstres de {zone:1446} peuvent lâcher, rarement, la Balise de détresse OOX-17/TN : gardez-la si vous en trouvez une.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "À l'ouest, les insectes Centipaar grouillent autour de leurs ruches ; n'importe lequel lâche les pièces.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "la {item:8526} pousse dans {zone:1425}, vers le niveau 48",
		["the {object:150075} in the square"] = "l'{object:150075} sur la place",
		["the {object:173265}"] = "les {object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, butin rare",
		["{item:8623}, a rare drop"] = "{item:8623}, butin rare",
		["{npc:5955}'s escort"] = "Escorte de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, à côté du maître des coursiers du vent",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "À l'est de la route, les Sangliers cendrés et les Grunters fouillent les pentes près des Basilics Rougepierre. Restez à l'écart des Sangliers infernaux de niveau 52, plus au sud.",
		["East of the village, the violet flower grows in the hills."] = "À l'est du village, le Tragan violet pousse dans les collines.",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Suivez les routes vers l'est à travers les {zone:1425} jusqu'au village troll de la côte est.",
		["Grind to 48"] = "Montez au niveau 48",
		["Highvale"] = "Haut-val",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Au nord le long de la côte, le panier de pique-nique de {npc:14731} est sur la petite île ; un {npc:14748} le garde.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Only if you are not level 48 yet."] = "Seulement si vous n'êtes pas encore niveau 48.",
		["Ride back north to the bloodmages."] = "Retournez au nord jusqu'aux mages de sang.",
		["Saltwater Snapjaws"] = "Gueules d'acier des mers",
		["Silvermane Howlers"] = "Hurleurs Crins-d'argent",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Au sud du gîte, les trolls Witherbark tiennent leurs villages. Chacun porte un crâne : avec vingt crânes, utilisez {item:15002} pour obtenir la Pique de Nimboya préparée, puis plantez-la dans le village.",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "Au sud-ouest, les Hurleurs Crins-d'argent rôdent dans les collines à l'est des villages Witherbark.",
		["The Vilebranch temples"] = "Les temples Vilebranch",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Les grosses tortues rampent sur les plages au nord du village. Les bouteilles de Porto Pupellyverbos de {npc:2491} se trouvent aussi sur ces plages, mais sa quête ne fait pas partie de cet itinéraire. Une Gueule d'acier des mers peut laisser tomber la Balise de détresse OOX-09/HL, rarement : gardez-la.",
		["The bloodmages"] = "Les mages de sang",
		["The central hills"] = "Les collines centrales",
		["The eastern slopes"] = "Les pentes de l'est",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "Les cinq quêtes demandent les mêmes morceaux : récupérez-les tous en un seul passage. À l'ouest de la route, les vautours ({npc:5982}), les Raillecrocs affamées, les Aiguillonneurs scorpok et les basilics Oeil-de-mort se partagent les collines.",
		["The northern beasts"] = "Les bêtes du nord",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Leurs quêtes suivantes redemandent les mêmes morceaux pour un objet d'amélioration et ne rapportent pas d'expérience : laissez-les.",
		["Vilebranch soothsayers"] = "Devins Vilebranch",
		["Vulture hills"] = "Collines des vautours",
		["for {npc:6986} in {zone:1454}, around level 50"] = "pour {npc:6986} à {zone:1454}, vers le niveau 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "pour {npc:7825} à {zone:1458}, vers le niveau 50",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "tuez des {npc:5982} sur les collines du nord, {zone:1419}",
		["{item:8704}, a rare drop"] = "{item:8704}, butin rare",
		["{npc:14731}'s lunch"] = "Le repas de {npc:14731}",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741} : pour {zone:1456}, vers le niveau 50",
		["{npc:7801}'s camp"] = "Camp de {npc:7801}",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Retournez au nord-est voir {npc:8420}.",
		["Back to {object:3202}"] = "Retour à {object:3202}",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Suivez la route vers le sud ; les basilics se prélassent sur les rochers à l'est, au milieu de la jungle. Leurs éclats tombent souvent.",
		["Frayfeather Hippogryphs"] = "Hippogryphes Aigreplume",
		["Highborne and Haldarr satyrs"] = "Bien-nés et satyres Haldarr",
		["Ironjaw Basilisks"] = "Basilics gueule de fer",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Gardez les livraisons pour {npc:4046}, {npc:8659} et {npc:6522} : vous passerez plus tard par {zone:1456}, {zone:1454} et {zone:1458}.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Gardez {quest:3444} : le coffre de {npc:7771} s'ouvre lors d'une visite ultérieure.",
		["Only once all three robots are home"] = "Seulement une fois les trois robots rentrés",
		["Ride into {zone:1447}"] = "Entrer en {zone:1447}",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Allez au sud-ouest jusqu'aux ruines. Les quatre tablettes s'y trouvent, gardées par les nagas Fouette-bile ; toute Sirène ou tout Myrmidon Fouette-bile peut porter la rune de {npc:8420}.",
		["Sea elementals"] = "Elémentaires marins",
		["Sprite Darters"] = "Fées fléchetteuses",
		["Take the zeppelin back to {zone:1454}."] = "Reprenez le zeppelin pour {zone:1454}.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Les fantômes bien-nés hantent les ruines juste au nord du sanctuaire ; les satyres Haldarr campent un peu plus au nord.",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Les Marcheurs des terres et les Géants des falaises parcourent les collines au nord du quai. Réduisez d'abord chacun avec l'{item:18904} : réduits, ils ne sont plus élites. Chaque géant réduit lâche un résidu ; utilisez aussi le récipient miniaturisé sur son corps.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "Les Elémentaires marins et les Embruns ondoient le long du rivage autour du quai.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "Le camp des elfes de sang se trouve juste au sud de {npc:8420}. Ses quatre pièces d'équipement sont dans les caisses autour du camp.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Les dragons féériques voltigent dans les bois juste à l'ouest du camp. Utilisez le récipient sur chacun de ceux que vous tuez.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Les hippogryphes nichent sur les collines au sud-ouest du camp. Tuez-en un, puis utilisez le récipient miniaturisé sur son corps.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Les tréants errent sur les routes forestières entre le camp et le centre de {zone:1444} ; ils sont peu nombreux, cherchez le long des chemins.",
		["The {object:2076} beside {npc:2519}"] = "Le {object:2076} à côté de {npc:2519}",
		["To {object:3202}"] = "Vers {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Plumes d'hippogryphe sans défaut",
		["Wandering Forest Walkers"] = "Marcheurs des bois errants",
		["Zapped giants"] = "Géants réduits",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, la Herse",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776} : les ours sont dans {zone:1448}",
