		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, dans l'Apothicarium",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957} : gardez-la pour {zone:1451}",
		["{npc:256386}'s crates"] = "Les caisses de {npc:256386}",
		["{npc:8393}, beside him"] = "{npc:8393}, à côté de lui",
		["{npc:8403}, nearby"] = "{npc:8403}, tout près",
		["{npc:8578}'s camp"] = "Le camp de {npc:8578}",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} se rend à {npc:10778}, dans {zone:1422} : gardez-la.",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["Both quests lead to {zone:1451}: keep them."] = "Les deux quêtes mènent à {zone:1451} : gardez-les.",
		["Hameya's mound"] = "Le monticule d'Hameya",
		["Hameya's scroll"] = "Le parchemin d'Hameya",
		["Hippogryph eggs"] = "Oeufs d'hippogryphe",
		["Moontouched Owlbeasts"] = "Chouettards lunaires",
		["On to {zone:1451}"] = "En route pour {zone:1451}",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel."] = "Les Chiens pestiférés et les Chiens pestiférés chétifs rôdent sur les rives du lac au sud-ouest de la chapelle.",
		["Sword of Marduk"] = "Epée brisée de Marduk",
		["The shattered sword lies on the ground north-west of the lake."] = "L'Epée brisée de Marduk gît au sol au nord-ouest du lac.",
		["The western hills"] = "Les collines de l'ouest",
		["The {object:142071} machine"] = "La machine {object:142071}",
		["{item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once."] = "La {item:15447} se gâte en dix minutes : tuez vite le Fléau de la ville et broyez aussitôt les sept morceaux avec le {item:15454}.",
		["{object:1661}'s flight master is in the {object:36078}'s west tower, outside the walls."] = "Le maître de vol de {object:1661} se trouve dans la tour ouest de {object:36078}, hors des murs.",
		["{quest:3914} goes back to Linken in Un'Goro: keep it."] = "{quest:3914} se rend à Linken, dans le Cratère d'Un'Goro : gardez-la.",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it if you have it."] = "Les cibles de {quest:5086} sont à {zone:1448}, lors d'un passage ultérieur : gardez la quête si vous l'avez.",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "Les objets de {quest:5168} se trouvent dans les zones des Maleterres visitées plus tard : gardez-la.",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Andorhal watchtowers and silos"] = "Tours de guet et silos d'Andorhal",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Retournez à Sudevent et montez dans la tour. Remuer la ruche au sommet fait sortir des Embusquées de la Ruche'Ashi ({npc:13301}) ; l'une porte {item:17346}.",
		["Dithers offers {item:14619} ({quest:838}). Skip it."] = "Dithers propose {item:14619} ({quest:838}). Passez-la.",
		["Dredge Crushers and Pincers"] = "Écraseurs térébrants et Pinceurs",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Les Frappeurs térébrants, les Scorpides Cinglepierre et les Glisseuses du sable se partagent les sables juste au nord du fort.",
		["Dredge and scorpids"] = "Térébrants et scorpides",
		["Flayers and Rock Stalkers"] = "Écorcheurs et Traqueuses des rochers",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Remontez vers le nord le long des dunes de l'ouest ; les Ecraseurs térébrants et les Pinceurs Cinglepierre rôdent d'ici jusqu'au fort.",
		["Mark {npc:10902} with the {item:12815}"] = "Marquez {npc:10902} avec {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marquez {npc:10903} avec {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marquez {npc:10904} avec {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marquez {npc:10905} avec {item:12815}",
		["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "Au nord, jusqu'au camp de bûcherons ; posez le tonneau de termites au milieu de la scierie.",
		["Ride east across the plaguelands to the chapel."] = "Traversez les maleterres vers l'est jusqu'à la chapelle.",
		["Ride north-west to {npc:1855}'s hut."] = "Allez vers le nord-ouest jusqu'à la cabane de {npc:1855}.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Allez vers le sud jusqu'à Andorhal. {npc:10667} attend dans l'auberge en ruine à l'ouest de la ville. Placez-vous sur le seuil de chacune des quatre tours avec {item:12815} pour la marquer ; restez en bordure de la ville. Utilisez {item:12627} près des silos au centre de la ville pour faire apparaître des Parasites temporels.",
		["Ride south-west to {npc:10667} in Andorhal."] = "Allez vers le sud-ouest jusqu'à {npc:10667}, à Andorhal.",
		["Ride west to the walled hold in the middle of the desert."] = "Allez vers l'ouest jusqu'au fort fortifié au milieu du désert.",
		["Scourge Champions"] = "Champions du Fléau",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Des Geysers de silithyste jaillissent dans le désert du sud. Marchez dans le silithyste qu'ils laissent et portez-le à l'extracteur de silithyste de la Horde, au camp de Kirika ; combattre ou monter en selle vous le fait lâcher.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Les Ecorcheurs Cinglepierre et les Traqueuses des rochers parcourent les dunes au sud-ouest du camp de Kirika.",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "Les fragments de tablette luisants jonchent le Campement du crépuscule, à l'extrême nord-ouest ; les Tempétueux de poussière et les Grondeurs du désert de l'endroit en laissent aussi tomber.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "La sacoche se trouve dans les montagnes de l'extrême sud, au-delà du Campement de Bronzebeard. Poigne-de-mort, un scorpide élite, patrouille à proximité : prenez-la pendant qu'il s'éloigne.",
		["The spare texts from the cultists"] = "Les textes en trop des cultistes",
		["Twilight Vanguard"] = "Avant-garde du Crépuscule",
		["Use {npc:10980} on {npc:10977}"] = "Utilisez {npc:10980} sur {npc:10977}",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "La bataille de Comté-de-Darrow, quête de {npc:10667}, se termine contre des élites. Passez-la.",
		["{npc:10926}'s own errand is not on this route. Skip it."] = "La quête propre à {npc:10926} ne fait pas partie de cet itinéraire. Passez-la.",
		["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803} arpente le camp de l'Avant-garde, à l'extrême sud-ouest. Chaque cultiste ici laisse tomber des Textes du crépuscule cryptés, quête ou non : récupérez-en vingt, dix pour {npc:15306} et dix pour Ortell.",
		["{npc:11878}' errands are not on this route. Skip them."] = "Les quêtes de {npc:11878} ne font pas partie de cet itinéraire. Passez-les.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} tient le camp de l'ouest.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, du côté ouest du fort",
		["{npc:1855}'s next task, Of Lost Honor, is not on this route. Skip it."] = "La tâche suivante de {npc:1855}, De l'honneur perdu, ne fait pas partie de cet itinéraire. Passez-la.",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Retournez dans le tunnel des Grumegueules et prenez la sortie de {zone:1452} ; {npc:9298} campe près des sources chaudes juste dehors.",
		["Back south to the Sanctuary, a short ride."] = "Retournez au sud au Sanctuaire d'émeraude, un court trajet.",
		["Dungeon instead of grinding"] = "Donjon au lieu de tuer des monstres",
		["From the {zone:1458}, take the zeppelin from the tower outside the city to {zone:1454}."] = "Depuis {zone:1458}, prenez le zeppelin de la tour hors de la ville pour {zone:1454}.",
		["Grind to 60"] = "Monter au niveau 60",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Facultatif : en groupe, un donjon 55-60 remplace l'enchaînement de monstres ci-dessous.",
		["South to the Sanctuary once more."] = "Retournez encore au sud au Sanctuaire d'émeraude.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "La quête suivante de {npc:10306}, {quest:4741}, vous ramènerait ici depuis {zone:1452}. Passez-la.",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "Le Coeur d'argent d'{npc:9116} demande un {item:11173} du nord de {zone:1448} et un retour ici. Passez-la.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298} vous envoie ensuite contre {npc:10738}, un élite dans sa grotte. Passez-la.",
} end)()
t.guides["forever/horde/orc-troll/01-durotar"] = (function() return {
		["Back at the Den"] = "De retour à l'Antre",
		["Back to the Den"] = "Retour à l'Antre",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Retournez voir {npc:5875} dans {object:172960}. Utilisez les {item:7464} sur le cercle d'invocation et vainquez le marcheur du Vide pour le lier.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Les sectateurs de la Lame ardente tiennent les grottes de {quest:827} ; chacun d'eux peut laisser tomber un {item:4871}. {npc:3204}, un démoniste de niveau 14, se tient au fond et laisse tomber l'{item:4903}.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Les Traqueurs corrompus parcourent la pente sous la grotte, du côté nord de la vallée.",
		["Follow the road north toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Suivez la route au nord vers {zone:1454}. {npc:3293} campe à côté ; les sacs volés traînent le long de la route au sud de lui.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libérez {npc:275811} et escortez-la hors de la Combe",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Dirigez-vous vers le sud à travers les îles. Les idoles des loas sont éparpillées sur les îles du sud ; les Trolls vaudous et les Trolls maléficiés les gardent et laissent tomber les Pendentifs maléficiés. {quest:826} et la cage de Minshina se trouvent sur l'île la plus au sud.",
		["Hit the sleeping peons north of the Den with the {item:16114}."] = "Frappez les péons endormis au nord de l'Antre avec la {item:16114}.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dans la grotte, allez tout droit à la première bifurcation, puis à droite, et suivez le ruisseau sur votre gauche jusqu'à la cascade : la pioche brille près de l'eau, derrière une colonne de roche.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dans la grotte, longez la paroi de droite tout du long, en passant le ruisseau : {npc:3183} attend au fond.",
		["Makrura and crawlers"] = "Makruras et clampants",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin."] = "Les makruras et les Clampants de l'écume bordent les plages au nord-est de Sen'jin.",
		["North end of the valley"] = "Extrémité nord de la vallée",
		["Prickly pears"] = "Figues de Barbarie",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Les Hurans et les Eclaireurs Tranchecrin tiennent les huttes à l'ouest de la ville ; les Lève-poussière et les Gardes de guerre tiennent les camps plus à l'ouest.",
		["Ridgeshade spiders"] = "Araignées noirecrête",
		["South-east shore"] = "Rivage sud-est",
		["Spitelash naga"] = "Nagas Fouette-bile",
		["Talk to {npc:3191}"] = "Parlez à {npc:3191}",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The foreman stands at the lumber pile east of the Den."] = "Le contremaître se tient près du tas de bois à l'est de l'Antre.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Les figues de Barbarie poussent parmi les huttes des huran juste à l'ouest de la ville.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Les armes traînent autour de l'Antre et du terrain d'entraînement ; les Sangliers tachetés parcourent tout le fond de la vallée.",
		["The wreckage"] = "L'épave",
		["Thunder lizards"] = "Lézards-tonnerre",
		["Thunder lizards across the river"] = "Lézards-tonnerre de l'autre côté du fleuve",
		["Training weapons and boars"] = "Armes d'entraînement et sangliers",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "Traversez à gué jusqu'à l'île de l'Écho la plus au nord. La Matriarche y rôde parmi les raptors.",
		["Wade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "Revenez à gué vers l'ouest jusqu'au rivage au sud de Sen'jin. Des Tigres de Durotar ({npc:3121}) y rôdent et les Oeufs de fouette-queue reposent dans des nids le long de la plage.",
		["Wake {quest:5441} with the {item:16114}"] = "Réveillez {quest:5441} avec la {item:16114}",
		["the {object:654925} on the ground beside her"] = "le {object:654925} par terre à côté d'elle",
		["{npc:10176}, where you start"] = "{npc:10176}, à votre point de départ",
		["{npc:265809}'s campfire"] = "Feu de camp de {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881} : enchanteurs uniquement, le résidu s'obtient en désenchantant des Pendentifs maléficiés",
		["{npc:266940}, on the east side of town"] = "{npc:266940}, du côté est de la ville",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, un jeune géant des mers, arpente la côte nord de {zone:1411}, au nord de la plage des nagas. {npc:275666} est élite : il est conseillé de se grouper.",
		["{npc:3102} hooves"] = "Sabots de {npc:3102}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142} : {npc:275666}, un géant des mers élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} se tient juste à l'entrée de la grotte ; {npc:3159} au fond de la grotte, derrière lui.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} attend dans l'Antre, le bâtiment juste à l'ouest de {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, dans la tour de guet",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, le maître des guerriers à côté de l'Antre",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, le maître des chasseurs à côté de l'Antre",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, le maître des voleurs dans l'Antre",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, le maître des démonistes au fond de la grotte",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, le maître des chamans à côté de l'Antre",
		["{npc:3159}, at the back of the cave"] = "{npc:3159}, au fond de la grotte",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} gît blessé au pied des collines au nord-ouest de l'Antre.",
		["{npc:3294}, by the inn"] = "{npc:3294}, près de l'auberge",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, pour {npc:6018} à {zone:1454} : gardez-la",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, le maître des prêtres à l'Antre",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, le maître des mages, à l'entrée de l'Antre",
		["{npc:5887} stands just outside the Den."] = "{npc:5887} se tient juste devant l'Antre.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887} : {npc:5873} et votre {item:5175}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} se tient sur la route, à la sortie est de la vallée.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, près du feu de cuisine",
		["{quest:790}, a large scorpid, prowls the slope south of {npc:3287} among the Scorpid Workers; pick the Cactus Apples by the cactuses on the way."] = "{quest:790}, un grand scorpide, rôde sur la pente au sud de {npc:3287} parmi les Scorpides ouvriers ; cueillez les Pommes de cactus près des cactus en chemin.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} campe sur la colline à l'ouest de la plage des nagas, au sud de {quest:827}.",
} end)()
t.guides["forever/horde/orc-troll/02-the-barrens"] = (function() return {
		["Back to the pirate camp: the boots are in the crate marked {object:3767} at the camp's south end, the lens in the Fragile crate just east of it."] = "Retournez au camp des pirates : les bottes sont dans la caisse marquée {object:3767} à l'extrémité sud du camp, la lentille dans la caisse Fragile juste à l'est.",
		["Plainstriders and raptors"] = "Trotteurs des plaines et raptors",
		["Razormane camp"] = "Camp Tranchecrin",
		["Southsea beach"] = "Plage des Mers du sud",
		["Wade into the pools to explore them"] = "Entrez dans les bassins pour les explorer",
		["Witchwing Slayers"] = "Tueuses Ensorçaile",
		["Witchwing harpies"] = "Harpies Ensorçaile",
		["Zhevra Runners graze on the same plains; finish the raptor heads as you go."] = "Les Messagers zhévras paissent dans les mêmes plaines ; terminez les têtes de raptor en chemin.",
		["Zhevra and raptors"] = "Zhévras et raptors",
		["{npc:3449}, on the tower platform: needs level 12"] = "{npc:3449}, sur la plateforme de la tour : niveau 12 requis",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} prépare le {item:6636} avec le goudron et la bourse. Utilisez-le près du brasero à côté de lui pour révéler la {npc:5893}, tuez-la pour obtenir la {item:6655}, puis placez la braise dans le brasero.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907} : {npc:2523}, votre {item:5176} et le {item:263412}",
