		["{quest:7837} to Exalted"] = "{quest:7837} jusqu'à Exalté",
		["{quest:7837} to Honored"] = "{quest:7837} jusqu'à Honoré",
		["{quest:7837} to Revered"] = "{quest:7837} jusqu'à Révéré",
} end)()
